krpano.action:
tween(scale, 1.06, 0.35, easeOutQuad);
if(hotspot[calc('glow_' + name)] !== null,
	tween(hotspot[calc('glow_' + name)].alpha, 0.7, 0.35);
);
tooltip_show(get(tooltip));

tween(scale, 1.0, 0.45, easeOutQuad);
if(hotspot[calc('glow_' + name)] !== null,
	tween(hotspot[calc('glow_' + name)].alpha, 0.0, 0.5);
);
tooltip_hide();

sound_ui_click();
tooltip_hide();
lookto(get(ath), get(atv), get(zoomfov), smooth(120, 20, 40), true, true,
	panel_open(get(panel));
	ambience_swell();
);

stopdelayedcall(toasthide);
set(layer[toast].html, %1);
set(layer[toast].visible, true);
tween(layer[toast].alpha, 1.0, 0.35);
delayedcall(toasthide, 2.8,
	tween(layer[toast].alpha, 0.0, 0.6, default, set(layer[toast].visible, false); );
);

tween(scale, calc(scale * 1.15), 0.15, easeOutQuad,
	tween(scale, calc(scale / 1.15), 0.3, easeOutBack); );
sound_egg_chime();
jsget(found_msg, calc('window.smDiscoveries ? smDiscoveries.message("' + %1 + '","' + %2 + '") : "you found " + "' + %2 + '"'));
toast_show(get(found_msg));

panel_close_instant();
set(layer[calc('panel_' + %1)].visible, true);
tween(layer[calc('panel_' + %1)].alpha, 1.0, 0.5, easeOutQuad);
set(panel_current, %1);
panel_open_extras();

if(panel_current !== null,
	panel_close_extras();
	tween(layer[calc('panel_' + panel_current)].alpha, 0.0, 0.4, easeInQuad,
		set(layer[calc('panel_' + panel_current)].visible, false);
	);
	set(panel_current, null);
	lookto(get(view.hlookat), 4, 92, smooth(100, 20, 30));
);

if(panel_current !== null,
	panel_close_extras();
	set(layer[calc('panel_' + panel_current)].alpha, 0.0);
	set(layer[calc('panel_' + panel_current)].visible, false);
	set(panel_current, null);
);
